sys_script_include.script:
var ChangeManagementUtils = Class.create();
ChangeManagementUtils.prototype = {
    initialize: function() {
    },
	createChangeFromProblem: function(sys_id) {
		var changeRecord = new GlideRecord('change_request');
		var currentProblem = new GlideRecord("problem");

		currentProblem.addQuery("sys_id",sys_id);
		currentProblem.query();
		changeRecord.initialize();

		if (currentProblem.next()) { 
			changeRecord.initialize();
			var changeModel = new GlideRecord("chg_model");
			changeModel.addQuery("name","Emergency");
			changeModel.query();
			changeModel.next();
			changeRecord.chg_model = changeModel.sys_id;
			changeRecord.type = 'emergency';
			changeRecord.cmdb_ci = currentProblem.cmdb_ci;
			changeRecord.short_description = currentProblem.short_description;
			changeRecord.description = currentProblem.description;
			changeRecord.u_source_problem = sys_id;
			return changeRecord.insert();
		}

	},

    type: 'ChangeManagementUtils'
};
